package ApanaCollegePattern2;

public class SquarePatternWithAlpha2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int n=3;
		char ch='A';
		for(int i=1;i<=n;i++)
		{
			
			for(int j=1;j<=n;j++)
			{
				System.out.print(ch+" " );
				ch++;
				
				}
			System.out.println();	
			
		}

	}

}
